93	func preparePersistedTranscriptionConfig(setting *storepb.InstanceAISetting, existing *storepb.InstanceAISetting) error {
94		// Preserve the previously stored transcription config when the request omits it,
95		// matching the same "absence == keep" semantics used for API keys. The preserved
96		// config still falls through to validation below, so a stale provider_id is
97		// rejected if the same update removed or renamed its referenced provider.
98		if setting.Transcription == nil && existing != nil {
99			setting.Transcription = existing.GetTranscription()
100		}
101		if setting.Transcription == nil {
102			return nil
103		}
104	
105		cfg := setting.Transcription
106		cfg.ProviderId = strings.TrimSpace(cfg.ProviderId)
107		cfg.Model = strings.TrimSpace(cfg.Model)
108		cfg.Language = strings.TrimSpace(cfg.Language)
109		cfg.Prompt = strings.TrimSpace(cfg.Prompt)
110	
111		if cfg.ProviderId != "" {
112			referenced := false
113			for _, provider := range setting.Providers {
114				if provider != nil && provider.Id == cfg.ProviderId {
115					referenced = true
116					break
117				}
118			}
119			if !referenced {
120				return errors.Errorf("transcription provider_id %q does not reference any configured provider", cfg.ProviderId)
121			}
122		}
123	
124		if len(cfg.Model) > maxTranscriptionConfigModelLength {
125			return errors.Errorf("transcription model is too long; maximum length is %d characters", maxTranscriptionConfigModelLength)
126		}
127		if len(cfg.Language) > maxTranscriptionConfigLanguageLength {
128			return errors.Errorf("transcription language is too long; maximum length is %d characters", maxTranscriptionConfigLanguageLength)
129		}
130		if len(cfg.Prompt) > maxTranscriptionConfigPromptLength {
131			return errors.Errorf("transcription prompt is too long; maximum length is %d characters", maxTranscriptionConfigPromptLength)
132		}
133		return nil
134	}
